//go:build arm64

package floats

// The NEON kernel of AllPass3Split32 (allpass32.go), generated by go-asmgen
// (allpass32_arm64_gen.go) into allpass32_arm64.s: four rows per step, the rows of a tail one
// at a time. NEON is the ARMv8-A baseline: no gate. The caller guarantees n >= 1 and the
// lengths of every operand. Every operand is passed as a pointer to its first element. No
// kernel keeps a pointer: go:noescape.
//
//go:noescape
func allPass3Split32NEON(n int, outre, outim, inre, inim, phire, phiim, q0re, q0im, q1re, q1im, q2re, q2im, c0, c1, c2 *float32,
	old0re, old0im, new0re, new0im, old1re, old1im, new1re, new1im, old2re, old2im, new2re, new2im *float32)

func allPass3Split32(n int, out, in Split32, t *AllPassRows32, old, cur *[3]Split32) {
	allPass3Split32NEON(n, &out.Re[0], &out.Im[0], &in.Re[0], &in.Im[0], &t.PhiRe[0], &t.PhiIm[0],
		&t.Q0Re[0], &t.Q0Im[0], &t.Q1Re[0], &t.Q1Im[0], &t.Q2Re[0], &t.Q2Im[0], &t.C0[0], &t.C1[0], &t.C2[0],
		&old[0].Re[0], &old[0].Im[0], &cur[0].Re[0], &cur[0].Im[0],
		&old[1].Re[0], &old[1].Im[0], &cur[1].Re[0], &cur[1].Im[0],
		&old[2].Re[0], &old[2].Im[0], &cur[2].Re[0], &cur[2].Im[0])
}
